<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1120;
        --panel: #111a2e;
        --panel-2: #0f172a;
        --border: #22304f;
        --text: #e5eefc;
        --muted: #9db0d0;
        --accent: #7c9cff;
        --accent-2: #9b7cff;
        --error: #ff7a90;
        --success: #5ee0a2;
        --shadow: 0 24px 60px rgba(0, 0, 0, 0.4);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 28%),
          linear-gradient(180deg, #060912 0%, var(--bg) 100%);
        color: var(--text);
        display: grid;
        place-items: center;
        padding: 24px;
      }

      .card {
        width: min(100%, 640px);
        background: linear-gradient(180deg, rgba(17, 26, 46, 0.95), rgba(10, 16, 31, 0.98));
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: 24px;
        box-shadow: var(--shadow);
        padding: clamp(24px, 4vw, 40px);
      }

      h1 {
        margin: 0 0 8px;
        font-size: clamp(1.75rem, 4vw, 2.4rem);
        line-height: 1.1;
      }

      .lede {
        margin: 0 0 28px;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 600;
        font-size: 0.95rem;
      }

      .required {
        color: var(--accent);
      }

      input,
      button {
        font: inherit;
      }

      input {
        width: 100%;
        border: 1px solid var(--border);
        border-radius: 14px;
        background: rgba(7, 12, 24, 0.7);
        color: var(--text);
        padding: 14px 16px;
        outline: none;
        transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
      }

      input::placeholder {
        color: #7283a8;
      }

      input:focus {
        border-color: rgba(124, 156, 255, 0.9);
        box-shadow: 0 0 0 4px rgba(124, 156, 255, 0.16);
      }

      .helper,
      .field-error,
      .status {
        margin: 0;
        font-size: 0.9rem;
        line-height: 1.45;
      }

      .helper {
        color: var(--muted);
      }

      .field-error {
        color: var(--error);
      }

      .field-error[hidden] {
        display: none;
      }

      .status {
        min-height: 1.4em;
        color: var(--success);
      }

      button {
        border: 0;
        border-radius: 14px;
        padding: 14px 18px;
        background: linear-gradient(135deg, var(--accent), var(--accent-2));
        color: white;
        font-weight: 700;
        cursor: pointer;
        transition: transform 0.18s ease, filter 0.18s ease;
        box-shadow: 0 10px 24px rgba(124, 156, 255, 0.28);
      }

      button:hover {
        filter: brightness(1.05);
        transform: translateY(-1px);
      }

      button:focus-visible {
        outline: 3px solid rgba(124, 156, 255, 0.45);
        outline-offset: 3px;
      }

      @media (max-width: 480px) {
        .card {
          padding: 20px;
          border-radius: 20px;
        }
      }
    </style>
  </head>
  <body>
    <main class="card">
      <h1>Contact support</h1>
      <p class="lede">Send us your details and we’ll get back to you as soon as possible.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            required
            aria-describedby="full-name-error"
          />
          <p class="field-error" id="full-name-error" hidden>Please enter your full name.</p>
        </div>

        <div class="form-field">
          <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
          <input
            id="email-address"
            name="email"
            type="email"
            autocomplete="email"
            required
            aria-describedby="email-error"
          />
          <p class="field-error" id="email-error" hidden>Please enter a valid email address.</p>
        </div>

        <div class="form-field">
          <label for="phone-number">Phone number</label>
          <input
            id="phone-number"
            name="phone"
            type="tel"
            autocomplete="tel"
            inputmode="tel"
            aria-describedby="phone-help phone-error"
            placeholder="+1 555 123 4567"
          />
          <p class="helper" id="phone-help">Optional. Use a phone number with country code when possible, for example +1 555 123 4567.</p>
          <p class="field-error" id="phone-error" hidden>Please enter a phone number in a valid format.</p>
        </div>

        <p class="status" id="form-status" role="status" aria-live="polite"></p>
        <button type="submit">Submit</button>
      </form>
    </main>

    <script>
      const form = document.getElementById("support-form");
      const fullName = document.getElementById("full-name");
      const email = document.getElementById("email-address");
      const phone = document.getElementById("phone-number");
      const status = document.getElementById("form-status");

      const phonePattern = /^\+?[0-9().\-\s]{7,}$/;
      const fields = [
        {
          input: fullName,
          error: document.getElementById("full-name-error"),
          validate: () => fullName.value.trim() !== "",
        },
        {
          input: email,
          error: document.getElementById("email-error"),
          validate: () => email.validity.valid && email.value.trim() !== "",
        },
        {
          input: phone,
          error: document.getElementById("phone-error"),
          validate: () => phone.value.trim() === "" || phonePattern.test(phone.value.trim()),
        },
      ];

      const showError = ({ input, error }, isVisible) => {
        error.hidden = !isVisible;
        input.setAttribute("aria-invalid", String(isVisible));
      };

      const validateField = (field) => {
        const valid = field.validate();
        showError(field, !valid);
        return valid;
      };

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const isValid = fields.map(validateField).every(Boolean);
        status.textContent = "";

        if (!isValid) {
          const firstInvalid = fields.find((field) => field.error.hidden === false);
          if (firstInvalid) {
            firstInvalid.input.focus();
          }
          return;
        }

        status.textContent = "Your message is ready to send.";
        form.reset();
        fields.forEach((field) => showError(field, false));
      });

      fields.forEach((field) => {
        field.input.addEventListener("input", () => {
          if (field.input.getAttribute("aria-invalid") === "true") {
            validateField(field);
          }
        });

        field.input.addEventListener("blur", () => {
          if (field.input.value.trim() !== "") {
            validateField(field);
          }
        });
      });
    </script>
  </body>
</html>
