      <p class="lede">Send us your details and we’ll get back to you as soon as possible.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            required
            aria-describedby="full-name-error"
          />
          <p class="field-error" id="full-name-error" hidden>Please enter your full name.</p>
        </div>

        <div class="form-field">
          <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
          <input
            id="email-address"
            name="email"
            type="email"
            autocomplete="email"
            required
            aria-describedby="email-error"
          />
          <p class="field-error" id="email-error" hidden>Please enter a valid email address.</p>
        </div>

        <div class="form-field">
