 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1" />
     <title>Support Contact Form</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #0b1120;
         --panel: #111a2e;
         --panel-2: #0f172a;
         --border: #22304f;
         --text: #e5eefc;
         --muted: #9db0d0;
         --accent: #7c9cff;
         --accent-2: #9b7cff;
         --error: #ff7a90;
         --success: #5ee0a2;
         --shadow: 0 24px 60px rgba(0, 0, 0, 0.4);
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 28%),
           linear-gradient(180deg, #060912 0%, var(--bg) 100%);
         color: var(--text);
         display: grid;
         place-items: center;
         padding: 24px;
       }

       .card {
         width: min(100%, 640px);
         background: linear-gradient(180deg, rgba(17, 26, 46, 0.95), rgba(10, 16, 31, 0.98));
         border: 1px solid rgba(255, 255, 255, 0.08);
         border-radius: 24px;
         box-shadow: var(--shadow);
         padding: clamp(24px, 4vw, 40px);
